 s.extra_c8_enabled=bool(required(0,0x329c,1));s.extra_c9_enabled=bool(required(0,0x46fc,1));check(required(0,0x4748+0x2c)==0,"extra c9 constructor empty");s.extra_c9_empty=true;s.extra_tail_count=scene_word(input,0,0x47a0);s.status_selector_a=scene_word(input,0,0x58);s.status_selector_b=scene_word(input,0,0x54);for(U i=0;i<3;++i){s.classification_masks[i]=scene_word(input,0,0x38+4*i);s.normal_thresholds[i]=scene_word(input,0,0x2c+4*i);}
