std::vector<StatusStore>read_stores(Reader&r,U bound){auto n=r.u();check(n<=bound,"contact store capacity");std::vector<StatusStore>out;for(U i=0;i<n;++i){StatusStore w{r.u(),r.u(),r.u(),r.u64()};check(w.width==1||w.width==2||w.width==4||w.width==8,"contact store width");if(w.width<8)check((w.value>>(8*w.width))==0,"contact store value width");out.push_back(w);}return out;}
ContactRecord read_contact(Reader&r,U ci,std::size_t scenes,const std::vector<std::span<const std::uint8_t>>&managers,const std::vector<std::span<const std::uint8_t>>&positions,const std::vector<std::span<const std::uint8_t>>&directions,const std::vector<std::span<const std::uint8_t>>&notifications){const auto n=r.u();check(n<=6*1024*1024,"contact record capacity");Reader q{r.take(n)};ContactRecord c;c.index=q.u();auto tag=q.u();c.inner=q.u();check(c.index==ci&&tag<=1&&(tag?c.inner==239+ci:c.inner<239),"contact record identity");if(tag)c.manager=read_manager(q,c.inner,positions,directions,notifications);else{const auto hash=digest(q);check(picosha2::hash256_hex_string(managers[c.inner].begin(),managers[c.inner].end())==hash,"exact prior manager record digest");Reader old{managers[c.inner]};c.manager=read_manager(old,c.inner,positions,directions,notifications);old.end();}c.scene=q.u();check(c.scene<scenes,"scene reference");auto nr=q.u();check(nr<=16384,"contact known range capacity");c.manager.known.clear();for(U i=0;i<nr;++i){auto a=q.u(),b=q.u();check(a<b&&(c.manager.known.empty()||c.manager.known.back().second<a),"contact knowledge order");c.manager.known.emplace_back(a,b);}auto&source=c.manager.position.direction.notification.status.post.original.row.c;source.known=c.manager.known;
 c.stop=q.u();c.sp=q.u();c.fpscr=q.u();const bool prefix=c.manager.position.direction.notification.status.prefix;check(c.stop==(prefix?0xb22508U:0xb14700U)&&c.sp==(prefix?0x3003e10U:0x3003ea0U),"contact exact contiguous checkpoint");tag=q.u();check(tag<=1&&bool(tag)==!prefix,"contact ABI presence");if(tag){c.abi.emplace();for(auto&x:*c.abi)x=q.u();check((*c.abi)[0]==caddr[0]+0xa000&&(*c.abi)[1]==caddr[0]&&(*c.abi)[2]==0&&(*c.abi)[3]==word(source.before[0],0x14)&&(*c.abi)[4]==caddr[14]&&(*c.abi)[5]==scene_address[0]&&(*c.abi)[6]==word(source.before[14],0x1c),"actual caller register delta singleton association");}
 auto count=q.u();check(count<=20000,"contact trace bound");for(U i=0;i<count;++i)c.trace.push_back(q.u());check(prefix?c.trace.empty():c.trace.size()>=10&&c.trace[0]==0xb146d8&&c.trace[1]==0xb146dc&&c.trace[2]==0xb146e0,"original contiguous contact entry");count=q.u();check(count<=4096,"contact call bound");for(U i=0;i<count;++i){Call a;a.pc=q.u();a.ret=q.u();a.value=q.u();for(auto&v:a.args)v=q.u();a.start=q.u();a.end=q.u();check(a.start>0&&a.start<=c.trace.size()&&a.end>=a.start&&a.end<=c.trace.size()&&c.trace[a.start-1]==a.pc,"contact ordered original call scope");c.calls.push_back(a);}tag=q.u();check(tag<=1,"scaled delta observation tag");if(tag)c.scaled_delta=q.u();c.stores=read_stores(q,10000);c.scene_stores=read_stores(q,10000);for(auto&h:c.hashes)h=digest(q);
 count=q.u();check(count<=2,"at most dispatch and contact queries");for(U i=0;i<count;++i){Query x;x.ret=q.u();x.height=q.u();x.classification=q.u();x.start=q.u();check(x.ret==0xb40cb4||x.ret==0xb315b4,"actual query caller return");for(auto&a:x.args)a=q.u();x.stack=q.bytes(20);check(x.args[0]==0x4600000&&x.args[1]==caddr[0]&&word(x.stack,0)==word(source.before[1],9,1),"source wrapper manager/Player/area ABI");x.current=q.bytes(12);x.previous=q.bytes(12);for(auto&a:x.before)a=q.u();for(auto&a:x.after)a=q.u();check(x.before[1]==0&&x.after[1]==0,"original nonnested grid depth");auto n0=q.u();check(n0<=3160,"source pair count bound");for(U j=0;j<n0;++j){auto v=q.u();check(v<3160,"original pair identity");x.pairs.push_back(v);}n0=q.u();check(n0<=3160,"face-call count bound");for(U j=0;j<n0;++j)x.faces.push_back(q.u());c.queries.push_back(std::move(x));}
 count=q.u();check(count<=1,"contact attribute extent");for(U i=0;i<count;++i){Attribute a;a.pointer=q.u();a.carrier=q.u();a.start=q.u();a.end=q.u();check(a.start<a.end&&a.pointer>=0x3000000&&a.pointer<=0x3004000-48,"attribute immediate observation identity");a.before=q.bytes(48);a.after=q.bytes(48);a.stores=read_stores(q,256);auto replay=a.before;for(const auto&w:a.stores)if(w.address>=a.pointer&&std::uint64_t(w.address)+w.width<=std::uint64_t(a.pointer)+48)put64(replay,w.address-a.pointer,w.value,w.width);same(replay,a.after,"immediate original attribute stores");same(Bytes(a.before.begin()+40,a.before.end()),Bytes(a.after.begin()+40,a.after.end()),"unwritten attribute tail exact raw preservation");c.attributes.push_back(std::move(a));}
 count=q.u();check(count==0||count==2,"opaque source word count");for(U i=0;i<count;++i){std::array<U,5>x;for(auto&a:x)a=q.u();check(x[0]==(i?0xb31670U:0xb31668U)&&x[2]==caddr[1]+0x498+4*i,"actual opaque copy source identity");c.tails.push_back(x);}q.end();return c;}
// Replay every original arena without masking opaque attribute copies. Semantic
// masks below apply only to outputs with no established attribute producer.
StatusRecord replay_contact(const ContactRecord&r,const SceneInput&input){auto expected=preceding(r.manager);std::array<Bytes,32>raw;for(U i=0;i<16;++i)raw[i]=expected.final[i];for(U i=0;i<4;++i)raw[16+i]=expected.final_extra[i];raw[20]=expected.post.original.wrappers;raw[21]=expected.post.diagnostic;raw[22]=expected.event_after;raw[23]=r.manager.position.direction.notification.queue_after;for(U i=0;i<5;++i)raw[24+i]=r.manager.before[i];for(U i=0;i<3;++i)raw[29+i]=input.raw[i];
 std::array<U,32>address{},size{};for(U i=0;i<20;++i){address[i]=caddr[i];size[i]=csize[i];}address[20]=0x3500000;address[21]=0x3600000;address[22]=0x3700000;address[23]=queue_base;size[20]=size[21]=size[22]=4096;size[23]=queue_size;for(U i=0;i<5;++i){address[24+i]=extra_address[i];size[24+i]=extra_size[i];}for(U i=0;i<3;++i){address[29+i]=scene_address[i];size[29+i]=scene_size[i];}
 auto apply=[&](const StatusStore&w,bool scene_only){bool found=false;for(U i=0;i<32;++i)if(w.address>=address[i]&&std::uint64_t(w.address)+w.width<=std::uint64_t(address[i])+size[i]){if(scene_only)check(i>=29,"declared Scene store region");else if(i>=29)return;put64(raw[i],w.address-address[i],w.value,w.width);found=true;if(scene_only)scene_store_bytes+=w.width;else contact_bytes+=w.width;}if(!found)check(w.address>=0x3000000&&std::uint64_t(w.address)+w.width<=0x3004000,"original other stores restricted to stack");};
 const auto previous_count=contact_bytes;for(const auto&w:r.manager.stores)apply(w,false);contact_bytes=previous_count;for(const auto&w:r.stores){apply(w,false);contact_total_bytes+=w.width;}for(const auto&w:r.scene_stores)apply(w,true);
 for(U i=0;i<32;++i){check(raw[i].size()==size[i],"complete contact arena extent");check(picosha2::hash256_hex_string(raw[i])==r.hashes[i],"complete contact original arena replay digest "+std::to_string(i));}
 for(U i=0;i<16;++i)expected.final[i]=std::move(raw[i]);for(U i=0;i<4;++i)expected.final_extra[i]=std::move(raw[16+i]);if(!expected.prefix)expected.comparison_masks.push_back({0,0xd2c,1,false});if(!r.tails.empty()){expected.comparison_masks.push_back({1,0x498,4,true});expected.comparison_masks.push_back({1,0x49c,4,true});for(const auto&t:r.tails)check(word(expected.final[1],t[2]-caddr[1])==t[3],"opaque word matches independent original store");}contact_stores+=r.stores.size();opaque_words+=r.tails.size();return expected;
}
placement::Fields position_fields(const Case&c){placement::Fields q;q.fieldd2c=field<std::uint8_t>(c,c.before,0,0xd2c,1);q.fieldd44=field<std::uint8_t>(c,c.before,0,0xd44,1);q.fieldd30_bits=field<U>(c,c.before,0,0xd30,4);q.fieldd34_bits=field<U>(c,c.before,0,0xd34,4);q.fieldd38_bits=field<U>(c,c.before,0,0xd38,4);q.fieldd64=field<U>(c,c.before,0,0xd64,4);q.euler_mode=field<std::uint16_t>(c,c.before,0,0x38,2);return q;}
void grid_equal(const sq::GridState&g,const std::array<U,3162>&expected,const cr::Resource&resource){check(g.resource.sha256()==resource.sha256()&&g.group==0&&g.counter==expected[0]&&g.depth==expected[1]&&g.pair_marks.size()==3160,"original grid binding/counter/depth/extent");for(U i=0;i<3160;++i)check(g.pair_marks[i]==expected[i+2],"original full pair stamps");}
void query_equal(const Query&q,const sq::HeightResult&h,const SceneInput&s,const std::vector<Attribute>&attributes){check(h.height_bits==q.height&&h.status==(q.classification&255)&&h.query.classification==q.classification,"original height and classification");check(h.query.effects.candidates.size()==q.pairs.size()&&h.query.effects.face_calls.size()==q.faces.size(),"original ordered candidate/face counts");for(U i=0;i<q.pairs.size();++i)check(h.query.effects.candidates[i]==sq::Candidate{0,0,q.pairs[i]},"original candidate order and instance identity");for(auto pointer:q.faces)check(pointer>=0x3000000&&pointer<0x3004000,"retained face argument is original temporary carrier identity");if(h.query.grid_updates.empty())check(q.before==q.after,"no native grid update matches original untouched grid");else{check(h.query.grid_updates.size()==1&&h.query.grid_updates[0].slot==0,"original single grid identity");grid_equal(h.query.grid_updates[0].state,q.after,s.source);}check(h.query.hit.has_value()==bool(q.classification),"original hit presence");if(h.query.hit)check(h.query.hit->resource.sha256()==s.source.sha256()&&h.query.hit->identity.instance==0&&h.query.hit->identity.group==0,"original hit source binding");
 if(q.ret==0xb315b4){check(h.attribute.has_value()==!attributes.empty(),"original direct attribute call presence");if(h.attribute){const auto&a=*h.attribute;const auto&raw=attributes[0].after;check(a.resource.sha256()==s.source.sha256()&&h.query.hit&&a.identity==h.query.hit->identity,"attribute same source identity");for(U i=0;i<6;++i)check(a.bytes0_5[i]==raw[i],"direct original attribute byte");for(U i=0;i<3;++i){check(a.words2_4_0[i]==word(raw,8+4*i),"direct original attribute words");check(a.normal_bits[i]==word(raw,0x18+4*i),"original source normal independent of hit normal");}check(a.word24==word(raw,0x24)&&!a.opaque28&&!a.opaque2c,"direct attribute zero and unwritten tail unknown");}}
 else check(!h.attribute,"dispatch original requested no attribute output");++contact_queries;contact_hits+=h.query.hit.has_value();
}
void scene_unchanged(const sq::Scene&a,const sq::Scene&b){check(a.instances.size()==b.instances.size()&&a.grid_states.size()==b.grid_states.size()&&a.other_empty==b.other_empty&&a.extra_c8_empty==b.extra_c8_empty&&a.extra_c8_enabled==b.extra_c8_enabled&&a.extra_c9_enabled==b.extra_c9_enabled&&a.extra_c9_empty==b.extra_c9_empty&&a.extra_tail_count==b.extra_tail_count&&a.status_selector_a==b.status_selector_a&&a.status_selector_b==b.status_selector_b&&a.classification_masks==b.classification_masks&&a.normal_thresholds==b.normal_thresholds,"borrowed Scene scalar metadata unchanged");for(U i=0;i<32;++i){check(a.direct[i].has_value()==b.direct[i].has_value(),"borrowed direct knowledge");if(a.direct[i]){check(a.direct[i]->size()==b.direct[i]->size(),"borrowed direct extent");for(U j=0;j<a.direct[i]->size();++j){const auto&x=(*a.direct[i])[j];const auto&y=(*b.direct[i])[j];check(x.instance==y.instance&&x.minimum_x==y.minimum_x&&x.maximum_z==y.maximum_z,"borrowed node unchanged");}}}for(U i=0;i<a.grid_states.size();++i){const auto&x=a.grid_states[i];const auto&y=b.grid_states[i];check(x.resource.sha256()==y.resource.sha256()&&x.group==y.group&&x.counter==y.counter&&x.depth==y.depth&&x.pair_marks==y.pair_marks,"borrowed source grid unchanged");}for(U i=0;i<a.instances.size();++i){const auto&x=a.instances[i];const auto&y=b.instances[i];check(x.enabled_5==y.enabled_5&&x.bypass_pair_box_33==y.bypass_pair_box_33&&x.object_mask==y.object_mask&&x.area_mask==y.area_mask&&x.exclusion_tag==y.exclusion_tag&&x.resource_present==y.resource_present&&x.tree_present==y.tree_present&&x.grid_present==y.grid_present&&x.status_count==y.status_count&&x.grid_state==y.grid_state&&x.resource.has_value()==y.resource.has_value(),"borrowed instance unchanged");if(x.resource)check(x.resource->sha256()==y.resource->sha256(),"borrowed resource identity unchanged");check(x.status.enabled_c==y.status.enabled_c&&x.status.disabled_1f==y.status.disabled_1f&&x.status.field20==y.status.field20&&x.status.pointer24_present==y.status.pointer24_present&&x.status.pointer30_present==y.status.pointer30_present,"borrowed status unchanged");}}
void compare_contact(const ContactRecord&r,const StatusRecord&expected,const SceneInput&s,const placement::Fields&before,const uc::Output&o){const auto&e=o.effects;std::vector<contact::CallKind>calls;for(const auto&c:r.calls)if(auto v=mh4u::test_contact_effects::call(c.pc))calls.push_back(*v);check(e.call_count==calls.size()&&calls.size()<=e.calls.size(),"original contact helper count");for(U i=0;i<calls.size();++i)check(e.calls[i]==calls[i],"original contact helper order");contact_calls+=calls.size();check(e.scaled_delta==r.scaled_delta,"original floating ABI scaled delta");const auto wrote=[&](U a){return std::any_of(r.stores.begin(),r.stores.end(),[&](const auto&w){return w.address==a;});};check(e.contact_written==wrote(caddr[1]+0x468)&&e.permission_written==wrote(caddr[0]+0xd2c)&&!e.radius_result,"original contact/permission publication and unentered radius");contact_writes+=e.contact_written;auto pos=before;pos.fieldd2c=std::uint8_t(word(expected.final[0],0xd2c,1));check(o.position==pos,"sole position fields owner and original d2c publication");
 const auto&dispatch=o.managed.positioned.directed.notified.status.adjusted.dispatched;std::vector<const sq::HeightResult*>heights;for(U i=0;i<dispatch.dispatch_count;++i)if(dispatch.dispatches[i].effects.spatial){const auto&a=*dispatch.dispatches[i].effects.spatial;if(a.height)heights.push_back(&*a.height);}const auto first=std::find_if(r.queries.begin(),r.queries.end(),[](auto&q){return q.ret==0xb40cb4;});check(heights.size()==U(first!=r.queries.end()),"original dispatch height count");if(first!=r.queries.end()){query_equal(*first,*heights[0],s,{});for(U i=0;i<dispatch.dispatch_count;++i)if(dispatch.dispatches[i].effects.spatial&&dispatch.dispatches[i].effects.spatial->height){const auto&sp=*dispatch.dispatches[i].effects.spatial;check(sp.current_point&&sp.previous_point,"original dispatch point observation presence");for(U k=0;k<3;++k)check((*sp.current_point)[k]==word(first->current,4*k)&&(*sp.previous_point)[k]==word(first->previous,4*k),"original dispatch current and previous vectors distinct");}}const auto last=std::find_if(r.queries.begin(),r.queries.end(),[](auto&q){return q.ret==0xb315b4;});check(e.height.has_value()==(last!=r.queries.end()),"original contact height count");if(last!=r.queries.end()){check(e.attribute_mask==word(last->stack,12)&&e.wrapper_flags==word(last->stack,8),"original wrapper masks transported");query_equal(*last,*e.height,s,r.attributes);}else check(!e.attribute_mask&&!e.wrapper_flags,"no invented query masks");
 if(o.grid_updates.empty()){for(const auto&q:r.queries)check(q.before==q.after,"empty returned plan only untouched original grid");}else{check(o.grid_updates.size()==1&&o.grid_updates[0].slot==0&&!r.queries.empty(),"cumulative grid plan identity");grid_equal(o.grid_updates[0].state,r.queries.back().after,s.source);}if(r.queries.size()==2){check(r.queries[0].after==r.queries[1].before,"original consecutive queries share latest grid state");check(r.queries[0].before[0]==0&&r.queries[0].after[0]==1&&r.queries[1].after[0]==2,"source observed two-query counter progression");}
}
